/**
* @brief  This function configures the TIM6 as a time base source.
*         The time source is configured to have 1ms time base with a dedicated
*         Tick interrupt priority.
* @note   This function is called  automatically at the beginning of program after
*         reset by HAL_Init() or at any time when clock is configured, by HAL_RCC_ClockConfig().
* @param  TickPriority: Tick interrupt priority.
* @retval HAL status
*/
HAL_StatusTypeDef HAL_InitTick (uint32_t TickPriority)
{
  /* In emulation, we don't need to set up hardware timers */
  /* We'll use the system's native timing mechanisms instead */

  /* Configure the TIM6 IRQ priority (keep for compatibility) */
  HAL_NVIC_SetPriority(TIM6_DAC_IRQn, TickPriority ,0U);

  /* Enable the TIM6 global Interrupt (keep for compatibility) */
  HAL_NVIC_EnableIRQ(TIM6_DAC_IRQn);

  /* Skip hardware timer initialization in emulation */
  /* Return success to allow program to continue */
  return HAL_OK;
}
